<?php $vehicle=$vehicle??[]; function vehicleValue(array $v,string $key): string{return htmlspecialchars((string)($v[$key]??''),ENT_QUOTES,'UTF-8');} ?>
<form id="<?= htmlspecialchars($formId,ENT_QUOTES,'UTF-8') ?>" data-vehicle-form data-vehicle-id="<?= (int)($vehicle['id']??0) ?>" class="vehicle-form"><div class="form-section"><div class="section-title"><h3>Identification du véhicule</h3><p>Caractéristiques et informations administratives.</p></div><div class="form-grid vehicle-form-grid">
<label class="field"><span>Immatriculation *</span><div><i data-lucide="rectangle-ellipsis"></i><input name="registration_number" value="<?= vehicleValue($vehicle,'registration_number') ?>" required maxlength="50" placeholder="Ex. 1234 AB 01"></div><small data-error="registration_number"></small></label><label class="field"><span>Type *</span><div><i data-lucide="truck"></i><select name="vehicle_type" required><option value="">Sélectionner</option><?php foreach(['Camion porteur','Tracteur routier','Semi-remorque','Fourgon','Pick-up','Utilitaire','Citerne','Plateau'] as $type): ?><option <?= ($vehicle['vehicle_type']??'')===$type?'selected':'' ?>><?= $type ?></option><?php endforeach; ?></select></div><small data-error="vehicle_type"></small></label>
<label class="field"><span>Marque *</span><div><i data-lucide="tag"></i><input name="brand" value="<?= vehicleValue($vehicle,'brand') ?>" required maxlength="100"></div><small data-error="brand"></small></label><label class="field"><span>Modèle *</span><div><i data-lucide="scan-line"></i><input name="model" value="<?= vehicleValue($vehicle,'model') ?>" required maxlength="100"></div><small data-error="model"></small></label>
<label class="field"><span>Année</span><div><i data-lucide="calendar"></i><input type="number" name="manufacture_year" value="<?= vehicleValue($vehicle,'manufacture_year') ?>" min="1950" max="<?= date('Y')+1 ?>"></div><small data-error="manufacture_year"></small></label><label class="field"><span>Couleur</span><div><i data-lucide="palette"></i><input name="color" value="<?= vehicleValue($vehicle,'color') ?>" maxlength="50"></div></label>
</div></div><div class="form-section"><div class="section-title"><h3>Capacité et exploitation</h3></div><div class="form-grid vehicle-form-grid"><label class="field"><span>Capacité *</span><div><i data-lucide="weight"></i><input type="number" step="0.01" min="0.01" name="capacity_value" value="<?= vehicleValue($vehicle,'capacity_value') ?>" required></div><small data-error="capacity_value"></small></label><label class="field"><span>Unité *</span><div><select name="capacity_unit"><option value="tonnes" <?= ($vehicle['capacity_unit']??'tonnes')==='tonnes'?'selected':'' ?>>Tonnes</option><option value="kg" <?= ($vehicle['capacity_unit']??'')==='kg'?'selected':'' ?>>Kilogrammes</option><option value="m³" <?= ($vehicle['capacity_unit']??'')==='m³'?'selected':'' ?>>Mètres cubes</option><option value="palettes" <?= ($vehicle['capacity_unit']??'')==='palettes'?'selected':'' ?>>Palettes</option></select></div><small data-error="capacity_unit"></small></label><label class="field"><span>Kilométrage</span><div><i data-lucide="gauge"></i><input type="number" step="0.1" min="0" name="mileage_km" value="<?= vehicleValue($vehicle,'mileage_km') ?>"></div><small data-error="mileage_km"></small></label><label class="field"><span>Statut *</span><div><i data-lucide="activity"></i><select name="status"><?php foreach(['Disponible','Affecté','En livraison','Maintenance','Indisponible'] as $status): ?><option <?= ($vehicle['status']??'Disponible')===$status?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select></div><small data-error="status"></small></label><label class="field"><span>Chauffeur affecté</span><div><i data-lucide="contact-round"></i><select name="assigned_driver_id"><option value="">Aucun chauffeur</option><?php foreach($drivers as $driver): ?><option value="<?= (int)$driver['id'] ?>" <?= (int)($vehicle['assigned_driver_id']??0)===(int)$driver['id']?'selected':'' ?>><?= htmlspecialchars($driver['first_name'].' '.$driver['last_name'].' · '.$driver['status'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><small data-error="assigned_driver_id"></small></label><label class="field"><span>Disponible à partir de</span><div><i data-lucide="clock"></i><input type="datetime-local" name="available_from" value="<?= !empty($vehicle['available_from'])?date('Y-m-d\TH:i',strtotime($vehicle['available_from'])):'' ?>"></div></label><label class="field full-span"><span>Notes internes</span><textarea name="notes" rows="3"><?= vehicleValue($vehicle,'notes') ?></textarea></label></div></div><div class="modal-actions vehicle-form-actions"><button type="button" class="button button-secondary" data-modal-close>Annuler</button><button type="submit" class="button button-primary"><i data-lucide="save"></i> <?= !empty($vehicle['id'])?'Enregistrer les modifications':'Créer le véhicule' ?></button></div></form>

